import { test, expect } from '@playwright/test';

test.describe('Total Price Update on Quantity Change', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should update total price when quantity is increased', async ({ page }) => {
    // Assuming there's a product with price and quantity controls
    const quantityInput = page.getByLabel(/quantity/i);
    const totalPriceDisplay = page.getByText(/total price/i);

    // Get initial total price
    const initialTotalText = await totalPriceDisplay.textContent();
    const initialTotal = parseFloat(initialTotalText?.replace(/[^\d.]/g, '') || '0');

    // Increase quantity
    await quantityInput.fill('2');
    await page.waitForTimeout(500); // Wait for price update

    // Get updated total price
    const updatedTotalText = await totalPriceDisplay.textContent();
    const updatedTotal = parseFloat(updatedTotalText?.replace(/[^\d.]/g, '') || '0');

    // Verify total price has increased
    expect(updatedTotal).toBeGreaterThan(initialTotal);
  });

  test('should update total price when quantity is decreased', async ({ page }) => {
    const quantityInput = page.getByLabel(/quantity/i);
    const totalPriceDisplay = page.getByText(/total price/i);

    // Set initial quantity to 3
    await quantityInput.fill('3');
    await page.waitForTimeout(500);

    const initialTotalText = await totalPriceDisplay.textContent();
    const initialTotal = parseFloat(initialTotalText?.replace(/[^\d.]/g, '') || '0');

    // Decrease quantity to 1
    await quantityInput.fill('1');
    await page.waitForTimeout(500);

    const updatedTotalText = await totalPriceDisplay.textContent();
    const updatedTotal = parseFloat(updatedTotalText?.replace(/[^\d.]/g, '') || '0');

    // Verify total price has decreased
    expect(updatedTotal).toBeLessThan(initialTotal);
  });

  test('should calculate correct total price based on unit price and quantity', async ({ page }) => {
    const quantityInput = page.getByLabel(/quantity/i);
    const unitPriceDisplay = page.getByText(/unit price|price per item/i);
    const totalPriceDisplay = page.getByText(/total price/i);

    // Get unit price
    const unitPriceText = await unitPriceDisplay.textContent();
    const unitPrice = parseFloat(unitPriceText?.replace(/[^\d.]/g, '') || '0');

    // Set quantity to 5
    const quantity = 5;
    await quantityInput.fill(quantity.toString());
    await page.waitForTimeout(500);

    // Get total price
    const totalPriceText = await totalPriceDisplay.textContent();
    const totalPrice = parseFloat(totalPriceText?.replace(/[^\d.]/g, '') || '0');

    // Verify calculation: total = unit price * quantity
    const expectedTotal = unitPrice * quantity;
    expect(Math.abs(totalPrice - expectedTotal)).toBeLessThan(0.01); // Allow for floating point precision
  });
});
